#include "nvx_gsp_channel_ring.h"
#include <assert.h>
#include <string.h>

static unsigned memory_creates, context_creates, maps, unmaps;
static unsigned context_destroys, memory_destroys;
static unsigned fail_create_stage;
static uint8_t backing[4096];

nvx_gsp_rmapi_status_t nvx_gsp_os_memory_create(nvx_gsp_rpc_manager_t*m,nvx_gsp_os_memory_t*x,uint32_t c,uint32_t d,uint32_t h,size_t n,uint32_t tag,void*s,size_t z,void*r,size_t q,uint32_t t,uint32_t p,nvx_gsp_rmapi_delay_fn f,void*k){(void)m;(void)s;(void)z;(void)r;(void)q;(void)t;(void)p;(void)f;(void)k;memory_creates++;assert(c==0x10&&d==0x20&&h==0x41&&n<=sizeof(backing)&&tag==NVX_GSP_CHANNEL_RING_TAG);x->client_handle=c;x->device_handle=d;x->memory_handle=0x40;x->requested_size=n;x->backing.acquired=1;x->backing.cpu_address=backing;x->stage=NVX_GSP_OS_MEMORY_CREATED;x->remote_created=1;return fail_create_stage==1?NVX_GSP_RMAPI_TIMEOUT:NVX_GSP_RMAPI_OK;}
nvx_gsp_rmapi_status_t nvx_gsp_os_memory_acquire(nvx_gsp_os_memory_t*x){assert(x->stage==NVX_GSP_OS_MEMORY_CREATED);x->lifetime_state++;return NVX_GSP_RMAPI_OK;}
nvx_gsp_rmapi_status_t nvx_gsp_os_memory_release(nvx_gsp_os_memory_t*x){assert(x->lifetime_state);x->lifetime_state--;return NVX_GSP_RMAPI_OK;}
nvx_gsp_rmapi_status_t nvx_gsp_os_memory_recover(nvx_gsp_rpc_manager_t*m,nvx_gsp_os_memory_t*x,void*s,size_t z,void*r,size_t q,uint32_t t,uint32_t p,nvx_gsp_rmapi_delay_fn f,void*k){(void)m;(void)x;(void)s;(void)z;(void)r;(void)q;(void)t;(void)p;(void)f;(void)k;return NVX_GSP_RMAPI_OK;}
nvx_gsp_rmapi_status_t nvx_gsp_os_memory_destroy(nvx_gsp_rpc_manager_t*m,nvx_gsp_os_memory_t*x,void*s,size_t z,void*r,size_t q,uint32_t t,uint32_t p,nvx_gsp_rmapi_delay_fn f,void*k){(void)m;(void)s;(void)z;(void)r;(void)q;(void)t;(void)p;(void)f;(void)k;assert(!x->lifetime_state);memory_destroys++;x->stage=NVX_GSP_OS_MEMORY_IDLE;x->remote_created=0;return NVX_GSP_RMAPI_OK;}
nvx_gsp_rmapi_status_t nvx_gsp_context_dma_create(nvx_gsp_rpc_manager_t*m,nvx_gsp_context_dma_t*x,uint32_t c,uint32_t d,uint32_t h,uint32_t mem,uint32_t sub,uint32_t flags,uint64_t off,uint64_t lim,void*s,size_t z,void*r,size_t q,uint32_t t,uint32_t p,nvx_gsp_rmapi_delay_fn f,void*k){(void)m;(void)s;(void)z;(void)r;(void)q;(void)t;(void)p;(void)f;(void)k;context_creates++;assert(c==0x10&&d==0x20&&h==0x30&&mem==0x41&&sub==1&&flags==0&&off==0&&lim==127);x->client_handle=c;x->device_handle=d;x->context_dma_handle=h;x->params.h_memory=mem;x->params.offset=off;x->params.limit=lim;x->stage=NVX_GSP_CONTEXT_DMA_CREATED;return NVX_GSP_RMAPI_OK;}
nvx_gsp_rmapi_status_t nvx_gsp_context_dma_recover(nvx_gsp_rpc_manager_t*m,nvx_gsp_context_dma_t*x,void*s,size_t z,void*r,size_t q,uint32_t t,uint32_t p,nvx_gsp_rmapi_delay_fn f,void*k){(void)m;(void)x;(void)s;(void)z;(void)r;(void)q;(void)t;(void)p;(void)f;(void)k;return NVX_GSP_RMAPI_OK;}
nvx_gsp_rmapi_status_t nvx_gsp_context_dma_destroy(nvx_gsp_rpc_manager_t*m,nvx_gsp_context_dma_t*x,void*s,size_t z,void*r,size_t q,uint32_t t,uint32_t p,nvx_gsp_rmapi_delay_fn f,void*k){(void)m;(void)s;(void)z;(void)r;(void)q;(void)t;(void)p;(void)f;(void)k;context_destroys++;x->stage=NVX_GSP_CONTEXT_DMA_IDLE;return NVX_GSP_RMAPI_OK;}
nvx_gsp_rmapi_status_t nvx_gsp_os_memory_dma_map(nvx_gsp_rpc_manager_t*m,const nvx_gsp_os_memory_t*x,const nvx_gsp_context_dma_t*c,nvx_gsp_dma_mapping_t*y,uint64_t o,uint64_t n,uint32_t fl,uint32_t f2,uint32_t ko,uint64_t doff,void*s,size_t z,void*r,size_t q,uint32_t t,uint32_t p,nvx_gsp_rmapi_delay_fn f,void*k){(void)m;(void)x;(void)c;(void)fl;(void)f2;(void)ko;(void)doff;(void)s;(void)z;(void)r;(void)q;(void)t;(void)p;(void)f;(void)k;maps++;assert(o==0&&n==128);y->request.length=n;y->dma_offset=0x200000;y->stage=NVX_GSP_DMA_MAP_MAPPED;return NVX_GSP_RMAPI_OK;}
nvx_gsp_rmapi_status_t nvx_gsp_os_memory_dma_unmap(nvx_gsp_rpc_manager_t*m,const nvx_gsp_os_memory_t*x,const nvx_gsp_context_dma_t*c,nvx_gsp_dma_mapping_t*y,void*s,size_t z,void*r,size_t q,uint32_t t,uint32_t p,nvx_gsp_rmapi_delay_fn f,void*k){(void)m;(void)x;(void)c;(void)s;(void)z;(void)r;(void)q;(void)t;(void)p;(void)f;(void)k;unmaps++;y->stage=NVX_GSP_DMA_MAP_IDLE;return NVX_GSP_RMAPI_OK;}
nvx_gsp_rmapi_status_t nvx_gsp_os_memory_dma_recover(nvx_gsp_rpc_manager_t*m,const nvx_gsp_os_memory_t*x,const nvx_gsp_context_dma_t*c,nvx_gsp_dma_mapping_t*y,void*s,size_t z,void*r,size_t q,uint32_t t,uint32_t p,nvx_gsp_rmapi_delay_fn f,void*k){(void)m;(void)x;(void)c;(void)y;(void)s;(void)z;(void)r;(void)q;(void)t;(void)p;(void)f;(void)k;return NVX_GSP_RMAPI_OK;}
static void delay(uint32_t ms,void*x){(void)ms;(void)x;}
int main(void){nvx_gsp_rpc_manager_t m={0};nvx_gsp_channel_ring_t r={0};uint8_t s[512],resp[512];assert(nvx_gsp_channel_ring_create(&m,&r,0x10,0x20,0x41,0x30,1,16,s,sizeof(s),resp,sizeof(resp),20,1,delay,0)==NVX_GSP_RMAPI_OK);assert(r.stage==NVX_GSP_CHANNEL_RING_READY&&r.bytes==128&&r.entries==(volatile uint32_t*)backing&&r.gpu_virtual_address==0x200000);assert(nvx_gsp_channel_ring_acquire(&r)==NVX_GSP_RMAPI_OK);assert(nvx_gsp_channel_ring_destroy(&m,&r,s,sizeof(s),resp,sizeof(resp),20,1,delay,0)==NVX_GSP_RMAPI_BUSY);assert(nvx_gsp_channel_ring_release(&r)==NVX_GSP_RMAPI_OK);assert(nvx_gsp_channel_ring_destroy(&m,&r,s,sizeof(s),resp,sizeof(resp),20,1,delay,0)==NVX_GSP_RMAPI_OK);assert(r.stage==NVX_GSP_CHANNEL_RING_IDLE&&unmaps==1&&context_destroys==1&&memory_destroys==1);return 0;}
